package com.kazurayam.wgetlog

import org.gradle.api.Project
import org.gradle.api.Plugin

/**
 * A Gradle plugin that transforms a log of GNU wget command
 * into a simpler line-oriented format.
 */
class DigestPlugin implements Plugin<Project> {
    void apply(Project project) {
        // Register a task
        project.tasks.register("wget-log-digest") {
            doLast {
                println("Hello from plugin 'com.kazurayam.wget-log-digest'")
            }
        }
    }
}
